create table public.property_staff_access_v3 (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, property_id uuid not null references public.properties_v2(id) on delete restrict, employee_user_id uuid not null references auth.users(id) on delete restrict, assignment_type text not null check (assignment_type in ('responsible','delegate','reader')), can_write boolean not null default false, valid_from timestamptz not null default now(), valid_until timestamptz, granted_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), revoked_at timestamptz, check (valid_until is null or valid_until > valid_from)); alter table public.property_staff_access_v3 enable row level security; create unique index one_active_responsible_v3 on public.property_staff_access_v3(property_id) where assignment_type='responsible' and revoked_at is null; create index property_staff_access_v3_org_idx on public.property_staff_access_v3(organization_id); create index property_staff_access_v3_employee_idx on public.property_staff_access_v3(employee_user_id);
